#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Trident dev app setup (#192, spec #179 story 79): every step only Justin can
# do so https://dev.app.tridentcubed.com signs in and saves to the real
# database. Run it from the repository root in Git Bash:
#
#   bash scripts/setup-dev-app.sh             the whole setup, optional parts last
#   bash scripts/setup-dev-app.sh microsoft   one optional part on its own, later
#                                             (geoapify, microsoft or resend)
#
# Values are kept in apps/app/.env (ignored by git, mode 0600), so a re-run
# offers each saved value again: press Enter to keep it. Secrets are typed
# hidden and never printed. Nothing here is committed.
#
# Dashboard steps checked against current docs on 2026-11-12:
#   confirmed  Better Auth callbacks /api/auth/callback/google and
#              /api/auth/callback/microsoft (better-auth.com docs)
#   confirmed  Google Auth Platform Clients page, Create client > Web
#              application, secret shown once (support.google.com 15549257);
#              Audience page and Publish app, basic scopes exception (15549945)
#   confirmed  Supabase Connect button > Transaction pooler, port 6543,
#              [YOUR-PASSWORD] placeholder, percent-encoding, prepared
#              statements off; Settings > API Keys for secret keys; the
#              password reset lives on the Database settings page
#   confirmed  Vercel CLI: vercel link --yes --project, vercel env add NAME
#              --environment production (CLI 64.7.0+) reading the value from
#              stdin, --force, --yes; Settings > Environments > Production >
#              Branch Tracking; Deployments > ... > Promote to Production
#              rebuilds with the Production values
#   confirmed  Microsoft Entra admin center > Entra ID > App registrations >
#              New registration, "Any Entra ID Tenant + Personal Microsoft
#              accounts" (learn.microsoft.com, 2026-05-14)
#   confirmed  Resend on Cloudflare: Sign in to Cloudflare (Domain Connect) or
#              three records (MX send, TXT send, TXT resend._domainkey,
#              DNS only), then Verify DNS Records
#   not checked, may have moved: the Google "Get started" branding form;
#              Supabase "Reset database password" and "Generate a password"
#              wording; the Vercel environment variable form labels and
#              Redeploy menu; Entra "Certificates & secrets" expiry choices
#              and whether a personal account must first make a free Azure
#              account; Resend API key permission names; Geoapify pages.

run_wizard() {

# ── Fixed facts ──────────────────────────────────────────────────────────
local ROOT
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
ENV_FILE="$ROOT/apps/app/.env"

APP_URL="https://dev.app.tridentcubed.com"
SUPABASE_REF="nugoenildurhgmvwnuuy"
SUPABASE_DASH="https://supabase.com/dashboard/project/$SUPABASE_REF"
VERCEL_TEAM="layerdbusiness"
VERCEL_PROJECT="tridentcubed-dev-app"
VERCEL_DASH="https://vercel.com/$VERCEL_TEAM/$VERCEL_PROJECT"
CORE_KEYS=(DATABASE_URL BETTER_AUTH_SECRET GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET SUPABASE_URL SUPABASE_SECRET_KEY)
VC=()           # the Vercel command line, once found
VERCEL_DIR=""   # a scratch folder linked to the Vercel project
VERCEL_STATE="" # empty until checked, then ready or manual

# ── Which parts to run ───────────────────────────────────────────────────
local parts=("$@") part
(( ${#parts[@]} )) || parts=(all)
for part in "${parts[@]}"; do
  case "$part" in
    all|geoapify|microsoft|resend) ;;
    *) printf 'Unknown part "%s". Use: all, geoapify, microsoft or resend.\n' "$part"; return 1 ;;
  esac
done
if [[ " ${parts[*]} " == *" all "* ]]; then
  parts=(core geoapify microsoft resend)
  TOTAL_STAGES=10
else
  TOTAL_STAGES=${#parts[@]}
fi

banner "Trident dev app: keys, database and Vercel"

for part in "${parts[@]}"; do
  case "$part" in
    core)
      stage_google
      stage_database
      stage_storage
      stage_session
      stage_vercel
      stage_merge
      stage_switch
      ;;
    geoapify)  stage_geoapify ;;
    microsoft) stage_microsoft ;;
    resend)    stage_resend ;;
  esac
done

if [[ -n "$VERCEL_DIR" ]]; then rm -rf "$VERCEL_DIR"; fi
finish
note "Saved values live in $ENV_FILE (never committed)."
note "Run one optional part later with: bash scripts/setup-dev-app.sh microsoft"
note "(or geoapify, or resend)."
printf '\n'
}

# ── Helpers for these stages ─────────────────────────────────────────────

# _have KEY... succeeds when every KEY already has a saved value.
_have() {
  local k
  for k in "$@"; do [[ -n "$(_existing "$k" || true)" ]] || return 1; done
}

# _redo "what" asks whether to redo a stage whose values are already saved.
# Enter (no) keeps them and skips the stage.
_redo() {
  note "$1 already saved from an earlier run."
  confirm "Redo this step anyway?"
}

# _optional "what" lets an optional stage be skipped. Enter skips it.
_optional() {
  note "Optional: skip it now and run it later on its own."
  confirm "Set up $1 now?"
}

# _urlencode VALUE percent-encodes a password for a connection string.
_urlencode() {
  local s="$1" out="" c i LC_ALL=C
  for (( i = 0; i < ${#s}; i++ )); do
    c=${s:i:1}
    case "$c" in
      [a-zA-Z0-9.~_-]) out+="$c" ;;
      *) printf -v c '%%%02X' "'$c"; out+="$c" ;;
    esac
  done
  printf '%s' "$out"
}

# _copy VALUE puts VALUE on the clipboard. Fails when no clipboard tool exists.
_copy() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v clip     >/dev/null 2>&1; then printf '%s' "$1" | clip
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# _is_secret NAME: whether NAME's value must never be shown on screen.
_is_secret() {
  case "$1" in GOOGLE_CLIENT_ID|MICROSOFT_CLIENT_ID|SUPABASE_URL) return 1 ;; esac
  return 0
}

# _vercel_setup finds the Vercel command line, signs in, and links a scratch
# folder to the project. Sets VERCEL_STATE to ready, or to manual when any
# part is missing, so the values are pasted by hand instead.
_vercel_setup() {
  [[ -z "$VERCEL_STATE" ]] || return 0
  VERCEL_STATE=manual
  local version major minor
  if command -v vercel >/dev/null 2>&1; then
    version=$(vercel --version 2>&1 | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n1 || true)
    major=${version%%.*}; minor=${version#*.}; minor=${minor%%.*}
    if [[ -n "$version" ]] && (( major > 64 || (major == 64 && minor >= 7) )); then
      VC=(vercel)
    fi
  fi
  if (( ! ${#VC[@]} )); then
    if ! command -v npx >/dev/null 2>&1; then
      warn "The Vercel command line isn't available, so you'll paste the values by hand."
      return 0
    fi
    say "The newest Vercel command line can put the values in for you."
    confirm "Fetch it for this run (takes a minute the first time)?" || return 0
    VC=(npx --yes vercel@latest)
  fi
  if ! "${VC[@]}" whoami >/dev/null 2>&1; then
    say "The Vercel command line isn't signed in yet."
    if confirm "Sign in now? It opens your browser."; then
      "${VC[@]}" login || true
    fi
    if ! "${VC[@]}" whoami >/dev/null 2>&1; then
      warn "Still not signed in, so you'll paste the values by hand."
      return 0
    fi
  fi
  VERCEL_DIR=$(mktemp -d)
  if "${VC[@]}" link --yes --project "$VERCEL_PROJECT" --scope "$VERCEL_TEAM" --cwd "$VERCEL_DIR" >/dev/null 2>&1; then
    VERCEL_STATE=ready
    printf '  %s✓ connected%s to the Vercel project %s\n' "$GREEN" "$RESET" "$VERCEL_PROJECT"
  else
    warn "Couldn't connect to the project $VERCEL_PROJECT, so you'll paste the values by hand."
  fi
}

# _paste NAME shows one value for pasting into the Vercel form. A secret goes
# to the clipboard, never the screen, unless Justin asks to see it.
_paste() {
  local name="$1" value
  value=$(_existing "$name" || true)
  if [[ -z "$value" ]]; then note "$name has no saved value yet, so skip it."; return 0; fi
  printf '\n  %sName:%s  %s\n' "$BOLD" "$RESET" "$name"
  if ! _is_secret "$name"; then
    printf '  %sValue:%s %s\n' "$BOLD" "$RESET" "$value"
    if _copy "$value" 2>/dev/null; then note "(the value is also on your clipboard)"; fi
  elif _copy "$value" 2>/dev/null; then
    note "The value is on your clipboard. Paste it into Value."
  elif confirm "No clipboard here. Show the secret on screen so you can copy it?"; then
    printf '  %sValue:%s %s\n' "$BOLD" "$RESET" "$value"
  else
    SKIPPED+=("Vercel value $name (it is saved in $ENV_FILE)")
    return 0
  fi
  pause "Saved it in Vercel? Press Enter for the next one."
}

# push_to_vercel NAME... puts each saved value in the Vercel project's
# Production environment: by the command line when it is ready, otherwise by
# showing each name for pasting.
push_to_vercel() {
  local name value err failed=()
  _vercel_setup
  if [[ "$VERCEL_STATE" == ready ]]; then
    for name in "$@"; do
      value=$(_existing "$name" || true)
      [[ -n "$value" ]] || continue
      if err=$(printf '%s' "$value" | "${VC[@]}" env add "$name" --environment production \
            --force --yes --scope "$VERCEL_TEAM" --cwd "$VERCEL_DIR" 2>&1 >/dev/null); then
        printf '  %s✓ set%s %s in Vercel (Production)\n' "$GREEN" "$RESET" "$name"
      else
        warn "Vercel refused $name: $(printf '%s' "$err" | tail -n1)"
        failed+=("$name")
      fi
    done
    (( ${#failed[@]} )) || return 0
    say "Paste the ones that failed by hand."
    set -- "${failed[@]}"
  fi
  open_url "$VERCEL_DASH/settings/environment-variables"
  step "For each name below: add an environment variable, type the Name,"
  step "paste the Value, choose Production only, and save."
  for name in "$@"; do _paste "$name"; done
}

# _redeploy_note explains that new values reach the live app only after a
# fresh build.
_redeploy_note() {
  say "New values reach the live app only after a fresh build:"
  open_url "$VERCEL_DASH/deployments"
  step "On the top deployment marked Current, click the three dots,"
  step "choose Redeploy, then confirm."
  pause "Press Enter once it says Ready."
}

# ── Core stages ──────────────────────────────────────────────────────────

stage_google() {
  stage "Google sign-in keys"
  say "These let you sign in to the app with your Google account."
  if _have GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET && ! _redo "The Google keys are"; then return 0; fi
  open_url "https://console.cloud.google.com/auth/overview"
  step "At the top, pick (or create) a Google Cloud project for Trident."
  step "If it shows Get started: app name Trident Cubed, your email as support"
  step "email, Audience External, your email as contact, agree, Create."
  step "Open Audience, click Publish app, confirm. Don't add a logo."
  pause "Press Enter for the sign-in client."
  open_url "https://console.cloud.google.com/auth/clients"
  step "Click Create client. Application type: Web application. Name: Trident dev app."
  step "Authorized JavaScript origins, Add URI:  $APP_URL"
  step "Authorized redirect URIs, Add URI:       $APP_URL/api/auth/callback/google"
  step "Click Create. The secret shows only now, so copy both values."
  ask GOOGLE_CLIENT_ID "Paste the Client ID (ends .apps.googleusercontent.com):"
  ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
}

stage_database() {
  stage "Database password and address"
  say "The app needs the database's address with its password inside."
  if _have DATABASE_URL && ! _redo "The database address is"; then return 0; fi
  warn "A new password disconnects anything still using the old one."
  if ! confirm "Reset the trident-dev database password now?"; then
    SKIPPED+=("DATABASE_URL: run this wizard again")
    return 0
  fi
  open_url "$SUPABASE_DASH/database/settings"
  step "Under Database password, click Reset database password."
  step "Click Generate a password, copy it, then save."
  local password template
  ask_secret DB_PASSWORD "Paste the new password (hidden):"
  password="$DB_PASSWORD"
  unset DB_PASSWORD
  open_url "$SUPABASE_DASH"
  step "Click Connect at the top of the page, then choose Transaction pooler."
  step "Copy the address as shown, with [YOUR-PASSWORD] still in it."
  note "It looks like postgresql://postgres.$SUPABASE_REF:[YOUR-PASSWORD]@...:6543/postgres"
  while :; do
    ask DB_TEMPLATE "Paste the address:"
    template="$DB_TEMPLATE"
    [[ "$template" == *"[YOUR-PASSWORD]"* && "$template" == *":6543/"* ]] && break
    warn "That isn't the Transaction pooler address with [YOUR-PASSWORD] in it (port 6543). Try again."
  done
  unset DB_TEMPLATE
  write_env DATABASE_URL "${template/\[YOUR-PASSWORD\]/$(_urlencode "$password")}"
  note "The wizard put the password in for you, encoded so any symbol is safe."
  pause "Press Enter to continue."
}

stage_storage() {
  stage "Photo storage key"
  say "This lets the app store photos in Supabase."
  if _have SUPABASE_URL SUPABASE_SECRET_KEY && ! _redo "The storage key is"; then return 0; fi
  write_env SUPABASE_URL "https://$SUPABASE_REF.supabase.co"
  open_url "$SUPABASE_DASH/settings/api-keys"
  step "Under Secret keys, copy the key that starts sb_secret_"
  step "(use its copy button; if there is none, create one named dev-app)."
  while :; do
    ask_secret SUPABASE_SECRET_KEY "Paste the secret key (hidden):"
    [[ "$SUPABASE_SECRET_KEY" == sb_secret_* ]] && break
    warn "That doesn't start with sb_secret_. Copy it again."
  done
  write_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
}

stage_session() {
  stage "Sign-in session secret"
  say "A random secret that keeps sign-ins safe. The wizard makes it: nothing to copy."
  if _have BETTER_AUTH_SECRET; then
    note "A secret is already saved. Making a new one signs everyone out."
    confirm "Make a new one anyway?" || return 0
  fi
  local secret
  if command -v openssl >/dev/null 2>&1; then
    secret=$(openssl rand -base64 32)
  else
    secret=$(head -c 32 /dev/urandom | base64)
  fi
  write_env BETTER_AUTH_SECRET "${secret//[$'\r\n']/}"
  pause "Press Enter to continue."
}

stage_vercel() {
  stage "Put the values in Vercel"
  say "The six values go into the Vercel project $VERCEL_PROJECT, Production only."
  push_to_vercel "${CORE_KEYS[@]}"
  pause "Press Enter to continue."
}

stage_merge() {
  stage "Land the work in dev"
  say "In the build thread (the chat where Claude built this), type this line:"
  printf '\n      %s/oneezy-merge into dev%s\n\n' "$BOLD" "$RESET"
  if _copy "/oneezy-merge into dev" 2>/dev/null; then note "(it's on your clipboard)"; fi
  say "Claude checks everything, then merges. The old prototype stays live meanwhile."
  pause "Press Enter once the build thread says it merged into dev."
}

stage_switch() {
  stage "Switch the app to dev"
  open_url "$VERCEL_DASH/settings/environments"
  step "Click Production, find Branch Tracking, change the branch to:  dev"
  step "Click Save."
  pause "Press Enter once it's saved."
  open_url "$VERCEL_DASH/deployments"
  step "Find the newest deployment from the dev branch, click its three dots,"
  step "choose Promote to Production, then confirm. It rebuilds with the new values."
  note "No dev deployment listed? Ask the build thread to push dev again."
  pause "Press Enter once it says Ready (a few minutes)."
  open_url "$APP_URL"
  step "Sign in with Google. You should land on the Dashboard as Super admin."
  step "Add a customer, a project and a photo; reload; download the PDF."
  note "Anything off? Tell the build thread what the screen said."
  pause "Press Enter to continue."
}

# ── Optional stages ──────────────────────────────────────────────────────

stage_geoapify() {
  stage "Place suggestions (Geoapify)"
  _optional "place suggestions" || return 0
  open_url "https://myprojects.geoapify.com"
  step "Sign in, open (or create) a project named Trident, and copy its API key."
  ask_secret GEOAPIFY_API_KEY "Paste the Geoapify API key (hidden):"
  write_env GEOAPIFY_API_KEY "$GEOAPIFY_API_KEY"
  push_to_vercel GEOAPIFY_API_KEY
  _redeploy_note
}

stage_microsoft() {
  stage "Microsoft sign-in"
  say "Needed for staff with @tridentcubed.com Microsoft mailboxes."
  _optional "Microsoft sign-in" || return 0
  open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
  step "Sign in with your own Microsoft account. If it asks you to make a free"
  step "Azure account first, do that, then come back to App registrations."
  step "Click New registration. Name: Trident dev app."
  step "Supported account types: Any Entra ID Tenant + Personal Microsoft accounts."
  step "Redirect URI: platform Web, address  $APP_URL/api/auth/callback/microsoft"
  step "Click Register, then copy the Application (client) ID from Overview."
  ask MICROSOFT_CLIENT_ID "Paste the Application (client) ID:"
  write_env MICROSOFT_CLIENT_ID "$MICROSOFT_CLIENT_ID"
  step "Open Certificates & secrets, then New client secret. Description: dev app,"
  step "the longest expiry offered, Add. Copy the Value column (not Secret ID) now."
  ask_secret MICROSOFT_CLIENT_SECRET "Paste the secret Value (hidden):"
  write_env MICROSOFT_CLIENT_SECRET "$MICROSOFT_CLIENT_SECRET"
  push_to_vercel MICROSOFT_CLIENT_ID MICROSOFT_CLIENT_SECRET
  _redeploy_note
}

stage_resend() {
  stage "Emailed sign-in codes (Resend)"
  say "Sends the six-digit code from noreply@tridentcubed.com."
  _optional "emailed codes" || return 0
  open_url "https://resend.com/domains"
  step "Click Add domain, type tridentcubed.com, keep the suggested region, Add."
  step "Easiest: click Sign in to Cloudflare and approve; it adds the records."
  step "By hand instead, in Cloudflare DNS add the three records Resend lists"
  step "(MX send, TXT send, TXT resend._domainkey) with Proxy status DNS only."
  note "They sit on send. and resend._domainkey, so your current email isn't touched."
  step "Back in Resend, click Verify DNS Records (minutes, sometimes hours)."
  pause "Press Enter for the API key."
  open_url "https://resend.com/api-keys"
  step "Click Create API key. Name: trident dev app, Sending access, domain"
  step "tridentcubed.com, Add. It shows only once, so copy it now."
  while :; do
    ask_secret RESEND_API_KEY "Paste the Resend API key (hidden):"
    [[ "$RESEND_API_KEY" == re_* ]] && break
    warn "Resend keys start with re_. Copy it again."
  done
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  push_to_vercel RESEND_API_KEY
  _redeploy_note
}

run_wizard "$@"; exit
